export type DrivingPovProps = Record<string, any>;

/* -------------------------------------------------------------------------- */
/*                                  COMPONENTS                                */
/* -------------------------------------------------------------------------- */

// Helper to project 3D coordinates to 2D screen
// Z goes from 0 (horizon) to 1 (camera)
const usePerspective = (width: number, height: number) => {
  const horizonY = height * 0.45;
  const centerX = width * 0.5;

  const project = (xPercent: number, z: number) => {
    // Non-linear Z for perspective effect (things get bigger faster as they get closer)
    // We map z (0-1) to a scale factor.
    // 0 is far away, 1 is close.
    const scale = Math.pow(z, 3); // Cubic curve for depth perception
    
    // Y position: starts at horizon, ends at bottom (plus some overscan)
    // We want z=0 -> y=horizonY, z=1 -> y=height*1.2
    const y = horizonY + (height * 1.5 - horizonY) * scale;
    
    // X position: 0 is center. -1 is left edge, 1 is right edge AT z=1.
    // At horizon (z=0), everything converges to centerX.
    // At camera (z=1), xPercent spreads out full width.
    const xOffset = (xPercent * width * 1.5) * scale; 
    const x = centerX + xOffset;

    return { x, y, scale, opacity: Math.min(1, z * 3) }; // Fade in from horizon
  };

  return { project, horizonY, centerX };
};

const LaneMarker: React.FC<{
  progress: number; // 0 to 1
  width: number;
  height: number;
  project: (x: number, z: number) => { x: number; y: number; scale: number; opacity: number };
}> = ({ progress, project }) => {
  const { x, y, scale, opacity } = project(0, progress); // Center of road
  
  if (progress <= 0 || progress >= 1.1) return null;

  return (
    <div
      style={{
        position: "absolute",
        left: x,
        top: y,
        width: 20 * scale, // Base width 20px
        height: 80 * scale, // Base height 80px
        backgroundColor: "rgba(255, 255, 255, 0.8)",
        transform: "translate(-50%, -50%)",
        opacity,
      }}
    />
  );
};

const RoadSideObject: React.FC<{
  progress: number;
  side: -1 | 1; // Left or Right
  type: "tree" | "sign" | "building";
  seed: number;
  width: number;
  height: number;
  project: (x: number, z: number) => { x: number; y: number; scale: number; opacity: number };
}> = ({ progress, side, seed, project, type }) => {
  const offset = 0.5 + (random(seed) * 0.5); // Random distance from road edge
  const { x, y, scale, opacity } = project(side * offset, progress);
  
  if (progress <= 0 || progress >= 1.2) return null;

  // Determine appearance based on type/random
  const isTree = type === "tree";
  const color = isTree 
    ? `rgb(${30 + random(seed)*20}, ${50 + random(seed)*40}, ${30 + random(seed)*20})` 
    : "#444";
    
  const objWidth = (isTree ? 150 : 100) * scale;
  const objHeight = (isTree ? 300 : 100) * scale;

  return (
    <div
      style={{
        position: "absolute",
        left: x,
        top: y - (objHeight * 0.9), // Anchor at bottom
        width: objWidth,
        height: objHeight,
        backgroundColor: color,
        borderRadius: isTree ? "50% 50% 10% 10%" : "2px",
        transform: "translate(-50%, 0)",
        opacity,
        zIndex: Math.floor(progress * 100),
      }}
    >
      {/* Simple detail for tree trunk or sign post */}
      <div 
         style={{
            position: 'absolute',
            bottom: 0,
            left: '40%',
            width: '20%',
            height: '20%',
            backgroundColor: '#221100'
         }}
      />
    </div>
  );
};

/* -------------------------------------------------------------------------- */
/*                                MAIN COMPONENT                              */
/* -------------------------------------------------------------------------- */
const DrivingPov: React.FC<DrivingPovProps> = ({
  backgroundColor = "#2a5298", // Morning Blue
  skyBottomColor = "#d38312", // Sunrise Orange
  transparentBackground = false,
  durationInSeconds = 10,
  title = "POV: You're running late",
  titleColor = "#4A90D9",
  shadowColor = "#808080",
  roadSpeed = 2,
  shakeIntensity = 2,
  showDashboard = true,
}) => {
  useFontLoader(["Roboto Condensed", "Inter"]);
  
  const frame = useCurrentFrame();
  const { width, height, fps } = useVideoConfig();
  const { project, horizonY, centerX } = usePerspective(width, height);

  // -- Animation State --
  const time = frame / fps;
  const scrollOffset = time * roadSpeed; // Continuous increasing value

  // -- Camera Shake --
  const shakeX = random(frame) * shakeIntensity - (shakeIntensity / 2);
  const shakeY = random(frame + 100) * shakeIntensity - (shakeIntensity / 2);

  // -- Steering Wheel Animation --
  // Subtle sine wave movement + random twitch
  const steerRot = Math.sin(time * 2) * 2 + (random(Math.floor(time * 5)) - 0.5) * 5;

  // -- Generate Objects --
  // We use modulo to loop objects. 
  // We need enough objects so the loop is seamless.
  const LANE_MARKER_COUNT = 10;
  const OBJECT_COUNT = 20;

  const laneMarkers = useMemo(() => {
    return new Array(LANE_MARKER_COUNT).fill(0).map((_, i) => i);
  }, []);

  const sceneryObjects = useMemo(() => {
    return new Array(OBJECT_COUNT).fill(0).map((_, i) => ({
        id: i,
        side: i % 2 === 0 ? -1 : 1, // Alternate sides
        type: i % 5 === 0 ? "building" : "tree", // mostly trees
        seed: i * 999
    }));
  }, []);

  // -- Render Helpers --
  // Gradient Sky
  const skyStyle: React.CSSProperties = {
    position: "absolute",
    top: 0,
    left: 0,
    width: "100%",
    height: "100%",
    background: transparentBackground 
        ? "transparent" 
        : `linear-gradient(to bottom, ${backgroundColor} 0%, ${skyBottomColor} ${horizonY / height * 100}%, #333 50%)`,
    overflow: "hidden",
    transform: `translate(${shakeX}px, ${shakeY}px)`,
  };

  return (
    <AbsoluteFill style={{ backgroundColor: "#000" }}>
        
        {/* 1. SKY & BACKGROUND */}
        <div style={skyStyle}>
            {/* Sun / Flare */}
            <div 
                style={{
                    position: 'absolute',
                    top: '20%',
                    left: '70%',
                    width: 200,
                    height: 200,
                    background: 'radial-gradient(circle, rgba(255,255,200,0.8) 0%, rgba(255,100,0,0) 70%)',
                    mixBlendMode: 'screen',
                    opacity: 0.6,
                }}
            />
            {/* Ground Plane (Grass) */}
            <div 
                style={{
                    position: 'absolute',
                    top: horizonY,
                    left: 0,
                    width: '100%',
                    height: '100%',
                    background: '#1a2b1a', // Dark green grass
                }}
            />
        </div>

        {/* 2. ROAD LAYER */}
        <div style={{
            position: 'absolute',
            width: '100%',
            height: '100%',
            transform: `translate(${shakeX}px, ${shakeY}px)`,
            perspective: 1000,
            overflow: 'hidden'
        }}>
            {/* Asphalt Triangle */}
            {/* We draw a trapezoid using clip-path for the road */}
            <div style={{
                position: 'absolute',
                left: '50%',
                top: horizonY,
                width: width * 4, // Wide enough to cover bottom corners
                height: height,
                backgroundColor: '#2A2A2A', // Road Color
                transform: 'translateX(-50%)',
                clipPath: 'polygon(45% 0, 55% 0, 100% 100%, 0% 100%)', // Tapers to horizon
            }} />

            {/* Lane Markers */}
            {laneMarkers.map((i) => {
                // Calculate position in loop (0 to 1)
                const loopPos = (scrollOffset + (i / LANE_MARKER_COUNT)) % 1;
                return (
                    <LaneMarker 
                        key={i} 
                        progress={loopPos} 
                        width={width} 
                        height={height} 
                        project={project} 
                    />
                );
            })}

            {/* Scenery (Trees/Signs) */}
            {sceneryObjects.map((obj) => {
                 // Slower scroll for scenery to give parallax depth or same speed?
                 // Usually road markers move faster if they are on the ground, 
                 // but relative to the car speed, everything stationary moves at same rate Z-wise.
                 const loopPos = (scrollOffset * 0.8 + (obj.id / OBJECT_COUNT)) % 1;
                 
                 // Don't render if it snaps back to horizon visibly
                 if (loopPos < 0.05) return null; 

                 return (
                    <RoadSideObject 
                        key={obj.id}
                        side={obj.side as -1 | 1}
                        type={obj.type as any}
                        seed={obj.seed}
                        progress={loopPos}
                        width={width}
                        height={height}
                        project={project}
                    />
                 );
            })}
        </div>

        {/* 3. COCKPIT / DASHBOARD LAYER */}
        {showDashboard && (
            <div style={{
                position: 'absolute',
                bottom: -20 + shakeY * 0.5, // Less shake on interior
                left: shakeX * 0.5,
                width: '100%',
                height: '100%',
                pointerEvents: 'none',
                display: 'flex',
                flexDirection: 'column',
                justifyContent: 'flex-end',
                alignItems: 'center',
            }}>
                {/* Dashboard Shape */}
                <div style={{
                    width: '120%',
                    height: '25%',
                    background: '#111',
                    borderRadius: '50% 50% 0 0',
                    marginBottom: -50,
                    boxShadow: 'inset 0 10px 20px rgba(0,0,0,0.8)',
                    zIndex: 10,
                    position: 'relative'
                }}>
                    {/* Dials / lights blur */}
                    <div style={{ position: 'absolute', left: '20%', top: '30%', width: 50, height: 50, borderRadius: '50%', background: 'radial-gradient(#00ff00 0%, transparent 70%)', opacity: 0.5 }} />
                    <div style={{ position: 'absolute', right: '20%', top: '30%', width: 50, height: 50, borderRadius: '50%', background: 'radial-gradient(#ff0000 0%, transparent 70%)', opacity: 0.5 }} />
                </div>

                {/* Steering Wheel Container */}
                <div style={{
                    position: 'absolute',
                    bottom: -150,
                    width: 600,
                    height: 600,
                    transform: `rotate(${steerRot}deg)`,
                    transformOrigin: '50% 50%',
                    zIndex: 20,
                }}>
                     {/* Wheel Ring */}
                     <svg width="600" height="600" viewBox="0 0 100 100">
                        {/* Outer Rim */}
                        <circle cx="50" cy="50" r="45" fill="none" stroke="#222" strokeWidth="8" />
                        {/* Inner Rim details */}
                        <circle cx="50" cy="50" r="45" fill="none" stroke="#111" strokeWidth="2" strokeDasharray="10 5" />
                        {/* Spokes */}
                        <path d="M 10 50 L 90 50" stroke="#222" strokeWidth="6" />
                        <path d="M 50 50 L 50 90" stroke="#222" strokeWidth="6" />
                        {/* Center Hub */}
                        <circle cx="50" cy="50" r="12" fill="#333" />
                     </svg>
                     
                     {/* Hands (Simple Shapes) */}
                     {/* Left Hand */}
                     <div style={{
                        position: 'absolute',
                        left: 40,
                        top: 250,
                        width: 80,
                        height: 100,
                        background: '#dcb', // Skin tone
                        borderRadius: 20,
                        transform: 'rotate(-20deg)',
                        boxShadow: '2px 2px 5px rgba(0,0,0,0.5)'
                     }} />
                     {/* Right Hand */}
                     <div style={{
                         position: 'absolute',
                         right: 40,
                         top: 250,
                         width: 80,
                         height: 100,
                         background: '#dcb',
                         borderRadius: 20,
                         transform: 'rotate(20deg)',
                         boxShadow: '-2px 2px 5px rgba(0,0,0,0.5)'
                     }} />
                </div>
            </div>
        )}

        {/* 4. OVERLAY / UI LAYER */}
        <div style={{
            position: 'absolute',
            top: '15%',
            left: '50%',
            transform: `translateX(-50%) translate(${shakeX * 0.2}px, ${shakeY * 0.2}px)`,
            textAlign: 'center',
            width: '80%',
            zIndex: 100,
        }}>
            <h1 style={{
                fontFamily: 'Roboto Condensed, sans-serif',
                fontSize: Math.min(width, height) * 0.08,
                color: titleColor,
                textTransform: 'uppercase',
                margin: 0,
                lineHeight: 1,
                letterSpacing: '-1px',
                textShadow: `3px 3px 0px ${shadowColor}`,
                fontWeight: 900,
                fontStyle: 'italic',
            }}>
                {title}
            </h1>
        </div>

        {/* Cinematic Vignette */}
        <AbsoluteFill style={{
            background: 'radial-gradient(circle, transparent 60%, rgba(0,0,0,0.6) 100%)',
            pointerEvents: 'none',
            zIndex: 200,
        }} />

    </AbsoluteFill>
  );
};

export default DrivingPov;